const WH = 'ERP: GET patient';

const wh = $(WH).first().json;
const h = wh.headers || {};
const meta = {
  from_agent: h['x-careos-agent'] || 'external',
  user_role: h['x-careos-role'] || 'unknown',
  user_ref: h['x-careos-user'] || '',
  task_id: h['x-careos-task'] || ('TASK-' + Date.now())
};
const clean = (r) => { const o = Object.assign({}, r); delete o.id; delete o.createdAt; delete o.updatedAt; return o; };
const rowsOf = (key) => $input.all().map(i => i.json).filter(r => r && r[key] !== undefined && r[key] !== null && r[key] !== '').map(clean);
const out = (http_code, status, data, action, patient_id, summary, reason) => [{ json: Object.assign({
  http_code: http_code, status: status, data: data, action: action, patient_id: patient_id || '',
  summary: summary, reason: reason || '',
  request: action + ' params=' + JSON.stringify(wh.params || {}) + ' query=' + JSON.stringify(wh.query || {})
}, meta) }];

const id = (wh.params || {}).id || '';
const rows = rowsOf('patient_id');
if (!rows.length) return out(404, 'not_found', null, 'GET /suvarna/patients/' + id, id, 'Patient ' + id + ' not found');
return out(200, 'success', rows[0], 'GET /suvarna/patients/' + id, id, 'Patient ' + rows[0].patient_name + ' returned');

